function download(name,text){const u=URL.createObjectURL(new Blob([text],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function markWords(text,r){if(prefs.mode==='extensive')return esc(text);let html='',pos=0;const vocab=r.vocabulary||[];const terms=vocab.map(v=>v.word).filter(Boolean).sort((a,b)=>b.length-a.length);if(!terms.length)return esc(text);const re=new RegExp('\\b('+terms.map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')\\b','gi');for(const m of text.matchAll(re)){html+=esc(text.slice(pos,m.index));const i=vocab.findIndex(v=>v.word.toLowerCase()===m[0].toLowerCase());html+=`<button class="word" data-word="${i}" aria-label="查看 ${esc(m[0])} 的词义">${esc(m[0])}</button>`;pos=m.index+m[0].length}return html+esc(text.slice(pos))}
let renderTicket=0;
