async function reader(id){const ticket=++renderTicket;let r=all.find(x=>x.id===id);if(!r){go();return}if(r.contentPath&&!r.loaded){app.innerHTML='<p class=empty>正在翻开文章…</p>';try{const response=await fetch(r.contentPath);if(!response.ok)throw Error('load');const full=await response.json();Object.assign(r,full,{loaded:true});if(ticket!==renderTicket)return}catch{if(ticket!==renderTicket)return;app.innerHTML='<p class=empty>文章暂时没有打开，请稍后再试。</p><button class=back id=retry>重新打开</button><button class=quiet id=returnShelf>返回书架</button>';$('#retry').onclick=()=>reader(id);$('#returnShelf').onclick=()=>location.hash='library';return}}window.LearningHistory?.visit(r,r.isNews?'news':'reading');last=id;save('naodai-english-last-v2',id);app.innerHTML=`<article class="reader ${prefs.mode==='extensive'?'mode-extensive':'mode-intensive'}"><button class="ui-icon-button back reader-back" id="back" aria-label="返回上一页" title="返回上一页"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m14 6-6 6 6 6"/><path d="M8 12h12"/></svg></button><h1 lang="en">${esc(r.title)}</h1><div class="byline">${author(r)}${r.isNews?' · '+esc(r.publishedAt)+' · 新闻学习改写':r.track&&r.track!=='classic'?' · 辅助阅读，非真题':''}</div>${r.editorialCorrection?`<aside class="small reading-correction" aria-label="原文勘误">${esc(r.editorialCorrection.text)} <a href="${esc(r.editorialCorrection.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(r.editorialCorrection.sourceLabel)} ↗</a>${r.editorialCorrection.additionalSourceUrl?` · <a href="${esc(r.editorialCorrection.additionalSourceUrl)}" target="_blank" rel="noopener noreferrer">周期说明 ↗</a>`:''}</aside>`:''}${editorialNotes(r)}${readingPhoto(r)}${r.vocabulary?.length&&prefs.mode!=='extensive'?'<p class="reading-hint">轻点有虚线的词，查看词义。</p>':''}<div class="reading" lang="en">${r.paragraphs.map(p=>`<p>${markWords(p,r)}</p>`).join('')}</div><button class="quiet" id="readingAids" aria-expanded="false" aria-controls="readingTools">阅读辅助 ⌄</button><div class="tools" id="readingTools" ${prefs.mode==='extensive'?'hidden':''}>${r.sentence?'<button class="pill" id="sentenceToggle" aria-expanded="false" aria-controls="sentencePanel">拆开一句</button>':''}${r.questions?.length?'<button class="pill" id="quizToggle" aria-expanded="false" aria-controls="quizPanel">试着理解</button>':''}<button class="pill" id="sourceToggle" aria-expanded="false" aria-controls="sourcePanel">原文与来源</button></div><section class="panel" id="sentencePanel" hidden></section><section class="panel" id="quizPanel" hidden></section><section class="source" id="sourcePanel" ${r.isNews?'':'hidden'}>${r.sourceUrl?`<a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">${r.isNews?'来源报道：':'原文：'}${esc(r.isNews?r.source:r.author)} · ${esc(r.bookTitle||r.title)} ↗</a><br>`:''}${esc(r.license)}${r.licenseUrl?`<br><a href="${esc(r.licenseUrl)}" target="_blank" rel="noopener noreferrer">查看许可条款 ↗</a>`:''}${r.revisionUrl?`<br><a href="${esc(r.revisionUrl)}" target="_blank" rel="noopener noreferrer">原文版本与作者记录 ↗</a>`:''}${r.attribution?`<br>${esc(r.attribution)}`:''}<br>${r.isNews?'本文是依据来源报道事实编写的英语学习短文，不是原文摘录或逐字翻译。':'本文为注明来源的原文节选，排版经过整理。中文释义、句子解析与练习（如有）为本站辅助内容。'}${r.downloadPath?`<br><a href="${esc(r.downloadPath)}" download>下载原始全文 ↓</a>`:''}</section><div class="finish">${r.isNews?`<label class="reading-completion"><input type="checkbox" id="finish" ${done.includes(id)?'checked':''}><span>已读完</span></label>`:`<button class="primary" id="finish">${done.includes(id)?'已读完 ✓':'读完这一篇'} <span>→</span></button>`}<span class="small" id="readStatus">${done.includes(id)?'读过 1 次':''}</span><button class="ui-icon-button quiet" id="next" aria-label="换一篇" title="换一篇"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M3 6h3c5 0 7 12 12 12h3M17 14l4 4-4 4M3 18h3c2 0 4-2 5-4M14 8c1-1 2-2 4-2h3M17 2l4 4-4 4"/></svg></button></div></article>`;AppNav.bind($('#back'),r.isNews?'news':'reading-home');$('#readingAids').hidden=prefs.mode!=='extensive';$('#readingAids').onclick=()=>{const tools=$('#readingTools');tools.hidden=!tools.hidden;$('#readingAids').setAttribute('aria-expanded',String(!tools.hidden));if(tools.hidden){for(const id of (r.isNews?['sentence','quiz']:['sentence','quiz','source'])){const panel=$('#'+id+'Panel'),button=$('#'+id+'Toggle');if(panel)panel.hidden=true;if(button)button.setAttribute('aria-expanded','false')}}};document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{const v=r.vocabulary[Number(b.dataset.word)];$('#noteLabel').textContent='词义 / WORD';$('#noteBody').innerHTML=`<div class="vocab-word" lang="en">${esc(v.word)}</div><p class="vocab-meaning">${esc(v.meaning)}</p><p class="vocab-context" lang="en">${esc(r.paragraphs.join(' ').split(/(?<=[.!?])\s/).find(s=>s.toLowerCase().includes(v.word.toLowerCase()))||'')}</p>`;window.ReaderTools?.beforeExternalDialog();$('#note').showModal()});if(r.sentence){$('#sentencePanel').innerHTML=`<span class="eyebrow">读懂一个句子</span><p class="sentence" lang="en">${esc(r.sentence.text)}</p><p class="translation">${esc(r.sentence.translation)}</p><p class="analysis">${esc(r.sentence.analysis)}</p>`;toggle('sentenceToggle','sentencePanel')}if(r.questions?.length){$('#quizPanel').innerHTML=r.questions.map((q,i)=>`<div class="quiz"><span class="eyebrow">${String(i+1).padStart(2,'0')} / 理解</span><p class="question" lang="en">${esc(q.prompt||q.question)}</p>${q.options.map((o,j)=>`<button class="option" lang="en" data-q="${i}" data-o="${j}">${String.fromCharCode(65+j)} · ${esc(o)}</button>`).join('')}<p class="explanation" id="explain${i}" role="status"></p></div>`).join('');document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{const q=r.questions[+b.dataset.q],correct=+b.dataset.o===q.answer;LearningInsights.record({id:'reading:'+r.id+':'+b.dataset.q,skill:q.skill||'阅读理解',correct});document.querySelectorAll(`[data-q="${b.dataset.q}"]`).forEach(x=>x.classList.remove('correct','incorrect'));b.classList.add(correct?'correct':'incorrect');$('#explain'+b.dataset.q).textContent=correct?'答对了。'+q.explanation:'再回原文找找线索。'+q.explanation});toggle('quizToggle','quizPanel')}toggle('sourceToggle','sourcePanel');if(r.isNews)$('#sourceToggle').hidden=true;const finishButton=$('#finish');const finishAction=()=>{if(!finishButton.isConnected||location.hash!=='#read/'+id)return;if(r.isNews&&!$('#finish').checked){done=done.filter(x=>x!==id);save('naodai-english-read-v2',done);window.LearningHistory?.complete(r,false);$('#readStatus').textContent='';ReaderTools.afterFinish(id,false);$('#readingReflection')?.remove();return}if(!done.includes(id)){done.push(id);save('naodai-english-read-v2',done)}const historySaved=window.LearningHistory?.complete(r,true);if(!r.isNews)$('#finish').innerHTML='已读完 ✓';$('#readStatus').textContent='读过 1 次';toast(historySaved===false?'本次已标记，浏览器未允许保存':'已记录在此浏览器');ReaderTools.afterFinish(id);if(prefs.mode==='intensive'&&r.questions?.length){$('#quizPanel').hidden=false;$('#quizToggle').setAttribute('aria-expanded','true');$('#quizPanel').scrollIntoView?.({block:'start',behavior:'auto'})}else if(prefs.mode==='extensive'){let reflection=$('#readingReflection');if(!reflection){reflection=document.createElement('p');reflection.id='readingReflection';reflection.className='small';reflection.textContent='回想一下：这篇主要讲了什么？能用一句话概括就很好。';$('.finish').after(reflection)}}};if(r.isNews)$('#finish').onchange=finishAction;else $('#finish').onclick=finishAction;$('#next').onclick=()=>{const pool=r.isNews?all.filter(n=>n.isNews):all.filter(n=>!n.isNews);go(pool[(pool.findIndex(x=>x.id===id)+1)%pool.length].id)};ReaderTools.attach(r,{toast,navigate:go,mode:prefs.mode,completed:done.includes(id)});const legacyHint=$('.reading-hint');if(legacyHint)legacyHint.remove()}
function toggle(button,panel){$('#'+button).onclick=()=>{const p=$('#'+panel);p.hidden=!p.hidden;$('#'+button).setAttribute('aria-expanded',String(!p.hidden))}}
function legacyRender(){const route=location.hash.slice(1),routeChanged=route!==lastRoute;AppNav.visit(route);if(route.startsWith('read/')&&!lastRoute.startsWith('read/'))previousSurface=lastRoute;lastRoute=route;document.body.classList.toggle('is-reading',route.startsWith('read/'));renderTicket++;if($('#note').open)$('#note').close();const hash=decodeURIComponent(location.hash.slice(1));if(hash==='test')vocabTest();else if(hash==='library')library();else if(hash.startsWith('read/'))reader(hash.slice(5));else englishHome();window.scrollTo(0,0)}
function onboard(){document.body.classList.add('is-onboarding');app.innerHTML=`<section class="home onboarding"><div class="eyebrow">英语</div><h1>这次，为哪一个目标读？</h1><div class="goal-choices">${Object.entries(TRACKS).filter(([k])=>k!=='classic').map(([k,v])=>`<button class="goal" data-goal="${k}">${v}<span>→</span></button>`).join('')}</div><p class="small">选好就开始，之后随时可以换。</p></section>`;document.querySelectorAll('[data-goal]').forEach(b=>b.onclick=()=>{selectedTrack=b.dataset.goal;save('naodai-track-v2',selectedTrack);document.body.classList.remove('is-onboarding');if(location.hash)location.hash='';else home()})}
function tune(){$('#noteLabel').textContent='调整推荐';$('#noteBody').innerHTML=`<p class="vocab-meaning">选择适合自己的阅读起点。</p><div class="track-tabs">${Object.entries(DIFF).map(([k,v])=>`<button class="pill" data-diff="${k}" aria-pressed="${difficulty===k}">${v}</button>`).join('')}</div><button class="primary" id="takeTest">试试词汇小测 →</button><p class="small">12 题，可随时退出。不估算词汇量或考试分数。</p><button class="quiet" id="switchGoal">更换考试方向</button>`;window.ReaderTools?.beforeExternalDialog();$('#note').showModal();document.querySelectorAll('[data-diff]').forEach(b=>b.onclick=()=>{difficulty=b.dataset.diff;save('naodai-difficulty-v2',difficulty);$('#note').close();recommendIndex=0;home()});$('#takeTest').onclick=()=>{$('#note').close();testAnswers=[];testIndex=0;location.hash='test'};$('#switchGoal').onclick=()=>{$('#note').close();selectedTrack=null;save('naodai-track-v2',null);onboard()}}
let testIndex=0,testAnswers=[],preferenceEdit=null;function finishPreferenceEdit(){const route=preferenceEdit?.returnRoute||'reading-home';preferenceEdit=null;return route}
function vocabTest(){document.body.classList.add('is-reading');const questions=window.VOCAB_CHECK;if(testIndex>=questions.length){const score=questions.filter((q,i)=>testAnswers[i]===q.answer).length;difficulty=score<=4?'easy':score<=8?'standard':'challenging';save('naodai-difficulty-v2',difficulty);recommendIndex=0;app.innerHTML=`<section class="test-page"><span class="eyebrow">你的阅读起点</span><h1>${DIFF[difficulty]}，开始试试。</h1><p class="subtitle">答对 ${score} / ${questions.length} 题。这个小测只帮助选择阅读起点，不估算词汇量或考试分数。</p><button class="primary" id="testFinish">看推荐 →</button><details><summary>查看答案与词义</summary>${questions.map((q,i)=>`<p><strong>${i+1}. ${esc(q.word)}</strong> · ${testAnswers[i]===q.answer?'正确':'再熟悉一下'}<br>${esc(q.explanation)}</p>`).join('')}</details></section>`;$('#testFinish').onclick=()=>{setPrefs({level:difficulty});navigate(prefs.mode?'reading-home':'setup-mode')};return}const q=questions[testIndex];app.innerHTML=`<section class="test-page"><button class="ui-icon-button back reader-back" id="exitTest" aria-label="退出小测" title="退出小测"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m14 6-6 6 6 6"/><path d="M8 12h12"/></svg></button><div class="eyebrow">词汇小测 · ${testIndex+1} / ${questions.length}</div><p class="sentence" lang="en">${esc(q.prompt||q.question)}</p><p class="small">这里的 ${esc(q.word)} 是什么意思？</p>${q.options.map((o,i)=>`<button class="option" data-answer="${i}">${esc(o)}</button>`).join('')}<button class="quiet" data-answer="-1">不确定，跳过这题</button><p class="small">可以直接退出，仍能阅读所有文章。</p></section>`;$('#exitTest').onclick=()=>{navigate(preferenceEdit?finishPreferenceEdit():(prefs.level?'reading-home':'setup-level'))};const expectedTestIndex=testIndex;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(!b.isConnected||testIndex!==expectedTestIndex)return;testAnswers[testIndex]=Number(b.dataset.answer);testIndex++;vocabTest()})}
let prefs=readStore('naodai-preferences-v3',{});
window.AppLearningBackup={snapshot:()=>({...prefs}),customReadings:()=>JSON.parse(JSON.stringify(custom)),replace:(value,history,imports)=>{prefs={...value};done=Object.keys(history.completed);custom=JSON.parse(JSON.stringify(imports));all=[...readings,...custom,...(window.ENGLISH_NEWS?.articles||[]).filter(n=>Array.isArray(n.paragraphs))];if(prefs.goal)selectedTrack=prefs.goal;if(prefs.level)difficulty=prefs.level}};
