function englishHome(){if(!guest){showLogin();return}if(!prefs.subject){subjects();return}document.body.classList.add('is-onboarding');app.innerHTML=`<section class="setup english-hub"><div class="english-hub-header"><button class="ui-icon-button back reader-back" id="englishSubjects" aria-label="返回选择科目" title="返回选择科目"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m14 6-6 6 6 6"/><path d="M8 12h12"/></svg></button><span class="eyebrow">英语</span><button class="ui-icon-button quiet account-entry" id="englishAccount" aria-label="我的" title="我的"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/></svg></button></div><h1>这次，想学什么？</h1><div class="level-choices"><button class="level-choice" id="chooseReading"><strong>阅读</strong><small>读文章，查词、拆句与批注</small><span aria-hidden="true">→</span></button><button class="level-choice" id="chooseVocabulary"><strong>词汇</strong><small>背单词，一起记相关短语</small><span aria-hidden="true">→</span></button></div><div class="english-personal"><button class="ui-icon-label quiet" id="englishWordbook" aria-label="我的词本" title="我的词本"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 3h13a2 2 0 0 1 2 2v16H6a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3M3 17h16M8 3v8l3-2 3 2V3"/></svg><span>词本</span></button><button class="ui-icon-label quiet" id="englishNotes" aria-label="全部笔记" title="全部笔记"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M6 3h14v18H6a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2M8 3v18M11 8h6M11 12h6M11 16h4"/></svg><span>笔记</span></button></div></section>`;$('#englishAccount').onclick=()=>navigate('account');$('#englishSubjects').onclick=()=>location.hash='subjects';$('#chooseReading').onclick=()=>enterEnglishActivity('reading');$('#chooseVocabulary').onclick=()=>enterEnglishActivity('vocabulary');$('#englishWordbook').onclick=()=>ReaderTools.openVocabulary();$('#englishNotes').onclick=()=>location.hash='notes'}
function setupGoal(target='reading'){document.body.classList.add('is-onboarding');app.innerHTML=`<section class="setup"><button class="ui-icon-button back reader-back" id="setupBack" aria-label="返回英语" title="返回英语"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m14 6-6 6 6 6"/><path d="M8 12h12"/></svg></button><span class="eyebrow">${target==='vocabulary'?'词汇 · 选择方向':'阅读 · 01 / 03'}</span><h1>你在为什么做准备？</h1><div class="goal-choices">${Object.entries(target==='vocabulary'?{cet4:'四级',cet6:'六级',postgrad:'考研',ielts:'雅思'}:TRACKS).filter(([k])=>k!=='classic').map(([k,v])=>`<button class="goal" data-goal="${k}">${v}<span>→</span></button>`).join('')}</div><p class="small">用来选择内容方向，以后也能换。</p></section>`;$('#setupBack').onclick=()=>navigate(preferenceEdit?finishPreferenceEdit():'english');document.querySelectorAll('[data-goal]').forEach(b=>b.onclick=()=>{if(!b.isConnected)return;setPrefs(target==='vocabulary'?{vocabularyGoal:b.dataset.goal,...(b.dataset.goal==='cet4'?{}:{goal:b.dataset.goal})}:{goal:b.dataset.goal});navigate(target==='vocabulary'?'vocabulary':preferenceEdit?finishPreferenceEdit():(prefs.level?(prefs.mode?'reading-home':'setup-mode'):'setup-level'))});}
function setupLevel(){document.body.classList.add('is-onboarding');app.innerHTML=`<section class="setup"><button class="ui-icon-button back reader-back" id="setupBack" aria-label="返回选择方向" title="返回选择方向"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m14 6-6 6 6 6"/><path d="M8 12h12"/></svg></button><span class="eyebrow">阅读 · 02 / 03</span><h1>从舒服的难度开始。</h1><div class="level-choices">${[['easy','轻松起步','优先较短、句子较直接的文章'],['standard','适中','中等篇幅，包含复合句和专业词汇'],['challenging','进阶','挑战长句、抽象观点和学术内容']].map(([k,t,desc])=>`<button class="level-choice" data-level="${k}"><strong>${t}</strong><small>${desc}</small><span>→</span></button>`).join('')}</div><p class="small">难度是选文的粗略分级，不是考试分数；同一篇原文不会随设置改写。</p><button class="quiet" id="setupTest">不确定？试试词汇小测 ↗</button></section>`;$('#setupBack').onclick=()=>navigate(preferenceEdit?finishPreferenceEdit():'setup-goal');document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{if(!b.isConnected)return;setPrefs({level:b.dataset.level});navigate(preferenceEdit?finishPreferenceEdit():'setup-mode')});$('#setupTest').onclick=()=>{testAnswers=[];testIndex=0;location.hash='test'}}
function setupMode(){document.body.classList.add('is-onboarding');app.innerHTML=`<section class="setup"><button class="ui-icon-button back reader-back" id="setupBack" aria-label="返回选择难度" title="返回选择难度"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m14 6-6 6 6 6"/><path d="M8 12h12"/></svg></button><span class="eyebrow">阅读 · 03 / 03</span><h1>你想怎样读？</h1><div class="level-choices"><button class="level-choice" data-mode="intensive"><strong>精读</strong><small>同难度优先有讲解的文章，读完展开理解练习</small><span>→</span></button><button class="level-choice" data-mode="extensive"><strong>泛读</strong><small>同难度广泛选文，收起辅助，读完回想大意</small><span>→</span></button></div></section>`;$('#setupBack').onclick=()=>navigate(preferenceEdit?finishPreferenceEdit():'setup-level');document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(!b.isConnected)return;setPrefs({mode:b.dataset.mode});recommendIndex=0;navigate(preferenceEdit?finishPreferenceEdit():'reading-home')})}
function recommendationOptions(){return {entries:readings,goal:prefs.goal,level:prefs.level,mode:prefs.mode,done:readings.filter(r=>done.includes(r.id)||window.LearningHistory?.readingState(r.id)).map(r=>r.id)}}
function recommended(advance=false){return window.ReadingRecommendations.select(recommendationOptions(),{advance})}
function recommendationsFinished(){const title=readings.some(r=>r.track===prefs.goal)?'这个方向的文章都读完了。':'这个方向暂时没有可推荐的文章。';app.innerHTML='<section class=library><button class=quiet id=finishedBack>返回英语</button><h1>'+title+'</h1><p class=small>可以去书架回顾，或调整阅读设置选择另一个方向。</p><button class=primary id=finishedLibrary>打开书架</button><button class=quiet id=finishedPreferences>学习偏好</button></section>';$('#finishedBack').onclick=()=>location.hash='english';$('#finishedLibrary').onclick=()=>location.hash='library';$('#finishedPreferences').onclick=openPreferences}
function readingPhoto(r,compact=false){const photos=window.READING_PHOTOS||[];const p=photos.find(p=>(p.suggestedReadingIds||[]).includes(r.id));if(!p)return '';const caption=p.captionsByReadingId?.[r.id]||p.captionZh||p.altZh||'';return `<figure class="reading-photo ${compact?'photo-compact':''}" data-photo-id="${esc(p.id)}"><img style="max-width:${Math.max(1,Number(p.width)||960)}px" src="photos/${esc(p.file)}" width="${p.width}" height="${p.height}" alt="${esc(p.altZh)}" decoding="async" loading="lazy"><figcaption>${!compact?`<span class="photo-caption">${esc(caption)}</span>`:''}<details class="photo-credit"><summary>图片来源</summary><p>${esc(p.author)} · <a href="${esc(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(p.license)}</a> · <a href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">查看原图 ↗</a>${compact?' · 封面裁切展示':''}</p>${p.usageNote?`<p>${esc(p.usageNote)}</p>`:''}${p.attribution?`<p>${esc(p.attribution)}</p>`:''}${p.changes?`<p>${esc(p.changes)}</p>`:''}</details></figcaption></figure>`}

function home(){if(!guest){showLogin();return}if(!prefs.subject){subjects();return}if(!prefs.goal){setupGoal();return}if(!prefs.level){setupLevel();return}if(!prefs.mode){setupMode();return}selectedTrack=prefs.goal;difficulty=prefs.level;const r=recommended();if(!r){recommendationsFinished();return}const news=window.ENGLISH_NEWS||{articles:[]};const newsTitle='新闻英语';app.innerHTML=`<section class="dashboard"><div class="dashboard-top"><button class="ui-icon-button quiet" id="subjectsLink" aria-label="返回英语" title="返回英语"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m14 6-6 6 6 6"/><path d="M8 12h12"/></svg></button><button class="ui-icon-button quiet" id="preferences" aria-label="学习偏好" title="学习偏好"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="var(--paper)"/><circle cx="16" cy="12" r="2" fill="var(--paper)"/><circle cx="9" cy="18" r="2" fill="var(--paper)"/></svg></button></div><div class="dashboard-heading"><h1>阅读</h1><button class="ui-icon-label quiet" id="libraryLink" aria-label="打开阅读书架" title="打开阅读书架"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 3v18M9 3v18M14 4l5-1 3 17-5 1z"/></svg><span>书架</span></button></div><div class="study-card"><div class="feature-top"><span class="eyebrow">推荐阅读</span><button class="ui-icon-button quiet" id="another" aria-label="换一篇" title="换一篇"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M3 6h3c5 0 7 12 12 12h3M17 14l4 4-4 4M3 18h3c2 0 4-2 5-4M14 8c1-1 2-2 4-2h3M17 2l4 4-4 4"/></svg></button></div>${readingPhoto(r,true)}<h2 lang="en">${esc(r.title)}</h2><p class="study-zh">${esc(r.titleZh||r.topic||'英文阅读')}</p><p class="study-preview" lang="en">${esc(r.preview||r.paragraphs[0].split(/(?<=[.!?])\s/).slice(0,1).join(' '))}</p><div class="study-card-bottom"><button class="primary" id="begin">开始学习 <span>→</span></button><span class="small">${count(r)} 词${r.difficulty?' · '+DIFF[r.difficulty]:''}${r.hasPractice||r.questions?.length?' · 含精读练习':' · 拓展阅读'}</span></div></div><details class="account-data exam-entry"><summary>专项练习</summary><p class="small">选一个方向，练习阅读方法。</p><div class="rt-actions"><button class="pill" data-exam-goal="cet4">四级</button><button class="pill" data-exam-goal="cet6">六级</button><button class="pill" data-exam-goal="postgrad">考研</button><button class="pill" data-exam-goal="ielts">雅思</button></div></details><section class="news-section"><div class="news-heading"><h2>${newsTitle}</h2><button class="quiet" id="moreNews">更多新闻 →</button></div>${news.articles.filter((n,i,a)=>a.findIndex(x=>x.topic===n.topic)===i).slice(0,3).map(newsCard).join('')}<p class="news-note">${esc(news.recommendedOn||'')} 整理 · 站内学习，来源见文末</p></section></section>`;$('#subjectsLink').onclick=()=>location.hash='english';$('#preferences').onclick=openPreferences;$('#another').onclick=e=>{if(!e.currentTarget?.isConnected||location.hash.slice(1)!=='reading-home')return;recommended(true);home()};$('#begin').onclick=()=>go(r.id);$('#libraryLink').onclick=()=>location.hash='library';$('#moreNews').onclick=()=>navigate('news');document.querySelectorAll('[data-exam-goal]').forEach(b=>b.onclick=()=>location.hash='practice/'+b.dataset.examGoal);bindNews()}
function openPreferences(){$('#noteLabel').textContent='英语学习偏好';$('#noteBody').innerHTML=`<div class="preference-list"><button id="editGoal"><span>考试方向</span><strong>${esc(TRACKS[prefs.goal])} ›</strong></button><button id="editLevel"><span>阅读难度</span><strong>${DIFF[prefs.level]} ›</strong></button><button id="editMode"><span>学习方式</span><strong>${prefs.mode==='intensive'?'精读':'泛读'} ›</strong></button></div><button class="quiet" id="takeVocab">试试词汇小测 ↗</button><p class="small">偏好和访客阅读记录仅保存在此浏览器。</p>`;window.ReadingRecommendations.mountPreferences($('#noteBody'),recommendationOptions(),level=>{setPrefs({level});$('#note').close();home()},openPreferences);window.ReaderTools?.beforeExternalDialog();$('#note').showModal();for(const [id,route]of[['editGoal','setup-goal'],['editLevel','setup-level'],['editMode','setup-mode']])$('#'+id).onclick=()=>{preferenceEdit={kind:route,returnRoute:location.hash.slice(1)||'reading-home'};navigate(route)};$('#takeVocab').onclick=()=>{testAnswers=[];testIndex=0;navigate('test')}}
let newsQuery='',newsTopic='',newsPage=0;
function newsCard(n){return `<button class="news-item news-card" data-news-read="${esc(n.id)}"><span class="news-source">${esc(n.source)} · ${esc(n.publishedAt)}${n.isArchive?' · 往期':''}</span><h3 lang="en">${esc(n.title)}</h3><span class="news-cn">${esc(n.titleZh)} · ${DIFF[n.difficulty]||'适中'} · ${count(n)} 词</span>${done.includes(n.id)?'<span class="news-read-state">✓ 读过 1 次</span>':''}<span class="news-arrow" aria-hidden="true">→</span></button>`}
function bindNews(){document.querySelectorAll('[data-news-read]').forEach(b=>b.onclick=()=>{if(b.isConnected)go(b.dataset.newsRead)})}
function newsRows(){const source=window.ENGLISH_NEWS?.articles||[],list=source.filter(n=>(!newsTopic||n.topic===newsTopic)&&(!newsQuery||(n.title+' '+n.titleZh+' '+n.source).toLowerCase().includes(newsQuery.toLowerCase())));newsPage=Math.min(newsPage,Math.max(0,Math.ceil(list.length/8)-1));$('#newsList').innerHTML=list.slice(newsPage*8,newsPage*8+8).map(newsCard).join('')||'<p class="empty">没有匹配的新闻，换个关键词试试。</p>';$('#newsPagination').innerHTML=list.length>8?`<button class="quiet" id="newsPrev" ${newsPage?'':'disabled'}>上一页</button><span class="small">${newsPage+1} / ${Math.ceil(list.length/8)}</span><button class="quiet" id="newsNext" ${(newsPage+1)*8>=list.length?'disabled':''}>下一页</button>`:'';if($('#newsPrev'))$('#newsPrev').onclick=()=>{newsPage--;newsRows()};if($('#newsNext'))$('#newsNext').onclick=()=>{newsPage++;newsRows()};bindNews()}
function showNews(){const news=window.ENGLISH_NEWS||{articles:[]},topics=[...new Set(news.articles.map(n=>n.topic))];app.innerHTML=`<section class="library news-library"><button class="ui-icon-button" id="newsBack" aria-label="返回上一页" title="返回上一页"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m14 6-6 6 6 6M8 12h12"/></svg></button><h1>新闻英语</h1><p class="small">基于真实报道整理的英文短读。站内查词、拆句、批注；原文链接在文末。</p><details class="news-filters"><summary>查找新闻</summary><label class="search-label" for="newsSearch">标题或来源</label><input id="newsSearch" class="search" type="search" value="${esc(newsQuery)}" placeholder="搜索新闻"><label class="news-topic" for="newsTopic">主题<select id="newsTopic"><option value="">全部</option>${topics.map(t=>`<option value="${esc(t)}" ${newsTopic===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label></details><div id="newsList"></div><div class="pagination" id="newsPagination"></div><p class="small">${esc(news.recommendedOn)} 整理 · 非实时自动更新 · 日期为来源报道日期，正文为本站学习改写</p></section>`;AppNav.bind($('#newsBack'),'reading-home');const input=$('#newsSearch');input.oninput=e=>{if(e.isComposing)return;newsQuery=input.value;newsPage=0;newsRows()};input.oncompositionend=()=>{newsQuery=input.value;newsPage=0;newsRows()};$('#newsTopic').onchange=e=>{newsTopic=e.target.value;newsPage=0;newsRows()};if(newsQuery||newsTopic)$('.news-filters').open=true;newsRows()}

let routeRenderSequence=0;async function render(){const initialFocus=document.activeElement;const renderSequence=++routeRenderSequence;window.MistakeReview?.cleanup?.();window.ExamPractice?.cleanup?.();window.LearningNotes?.cleanup();window.WordLearning?.cleanup();window.ReaderTools?.cleanup();const route=location.hash.slice(1),routeChanged=route!==lastRoute;AppNav.visit(route);if(route.startsWith('read/')&&!lastRoute.startsWith('read/'))previousSurface=lastRoute;lastRoute=route;document.body.classList.remove('is-onboarding');document.body.classList.toggle('is-content-surface',(['reading-home','news','account','history','activity','library','notes','wordbook','words','vocabulary','mistakes'].includes(route)||route.startsWith('mistakes/')));document.body.classList.toggle('is-reading',route.startsWith('read/')||route==='test'||route.startsWith('practice/'));document.body.classList.toggle('is-vocabulary',route==='vocabulary');renderTicket++;if($('#note').open)$('#note').close();if(!guest){document.body.classList.remove('is-reading','is-vocabulary');showLogin();return}if(route==='mistakes'||route.startsWith('mistakes/'))await MistakeReview.render(app,{route,entries:all});else if(route==='subjects')subjects();else if(route==='english')englishHome();else if(route.startsWith('practice/')&&['cet4','cet6','postgrad','ielts'].includes(route.split('/')[1]))await ExamPractice.render(app,{goal:route.split('/')[1],toast,onBack:()=>AppNav.back('reading-home'),onResult:r=>LearningInsights.record({id:'exam:'+r.questionId,skill:r.skillLabel||r.skill,correct:r.correct,at:r.attemptedAt})});else if(route==='reading-home')home();else if(route==='news')showNews();else if(['account','history','activity'].includes(route))LearningHistory.render(app,{route,entries:all});else if(route==='setup-goal-vocabulary')setupGoal('vocabulary');else if(route==='setup-goal')setupGoal();else if(route==='setup-level')setupLevel();else if(route==='setup-mode')setupMode();else if(route==='test')vocabTest();else if(route==='vocabulary'){if(!(prefs.vocabularyGoal||prefs.goal))setupGoal('vocabulary');else await WordLearning.render(app,{toast,goal:prefs.vocabularyGoal||prefs.goal,onGoal:goal=>setPrefs({vocabularyGoal:goal,...(goal==='cet4'?{}:{goal})})})}else if(route==='notes')LearningNotes.render(app,{toast});else if(route==='words'||route==='wordbook')ReaderTools.renderVocabulary(app,{toast});else if(route==='library')library();else if(route.startsWith('read/'))await reader(route.slice(5));else englishHome();if(renderSequence!==routeRenderSequence||route!==location.hash.slice(1))return;const restoring=refreshState?.route===route;const restore=restoring?refreshState.scrollY:0;if(routeChanged&&!restoring&&!$('#note').open&&(!document.activeElement||document.activeElement===document.body||!document.activeElement.isConnected||document.activeElement===initialFocus)){const heading=app.querySelector('h1')||app;if(!heading.hasAttribute('tabindex'))heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true})}refreshState=null;window.scrollTo(0,Number.isFinite(restore)?restore:0);if(!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)app.firstElementChild?.animate?.([{opacity:.94,transform:'translateY(3px)'},{opacity:1,transform:'translateY(0)'}],{duration:140,easing:'ease-out'})}
const UI_SESSION='naodai-ui-session-v1';let refreshState=null;
try{const saved=JSON.parse(sessionStorage.getItem(UI_SESSION)||'null');const isReload=performance.getEntriesByType?.('navigation')?.[0]?.type==='reload';if(isReload&&!location.hash&&saved?.route&&/^(reading-home|news|account|history|activity|library|vocabulary|wordbook|words|notes|setup-goal|setup-level|setup-mode|test|practice\/(cet4|cet6|postgrad|ielts)|read\/[a-zA-Z0-9_-]+|mistakes(?:\/(?:exam\/[a-zA-Z0-9_-]+|reading\/[a-zA-Z0-9_-]+\/(?:0|[1-9]\d{0,4})))?)$/.test(saved.route))history.replaceState(null,'','#'+saved.route);if(saved&&saved.route===location.hash.slice(1)){refreshState=saved;const l=saved.library||{};query=String(l.query||'').slice(0,300);topicFilter=String(l.topicFilter||'');difficultyFilter=DIFF[l.difficultyFilter]?l.difficultyFilter:'';shelfPage=Math.max(0,Number(l.shelfPage)||0);if(TRACKS[l.selectedTrack])selectedTrack=l.selectedTrack;newsQuery=String(saved.news?.query||'').slice(0,300);newsTopic=String(saved.news?.topic||'');newsPage=Math.max(0,Number(saved.news?.page)||0);if(saved.preferenceEdit&&['setup-goal','setup-level','setup-mode'].includes(saved.preferenceEdit.kind)&&saved.preferenceEdit.returnRoute==='reading-home')preferenceEdit=saved.preferenceEdit;if(saved.route==='test'&&Array.isArray(saved.test?.answers)){testAnswers=saved.test.answers.filter(n=>Number.isInteger(n)&&n>=-1&&n<=3).slice(0,12);testIndex=Math.min(testAnswers.length,window.VOCAB_CHECK.length)}}}catch{}
function saveUIState(){try{sessionStorage.setItem(UI_SESSION,JSON.stringify({route:location.hash.slice(1),scrollY:window.scrollY||0,library:{query,topicFilter,difficultyFilter,shelfPage,selectedTrack},news:{query:newsQuery,topic:newsTopic,page:newsPage},preferenceEdit,test:{answers:testAnswers,index:testIndex}}))}catch{}}
addEventListener('pagehide',saveUIState);addEventListener('beforeunload',saveUIState);
$('#shelf').onclick=()=>location.hash='library';$('#closeNote').onclick=()=>$('#note').close();$('#note').onclick=e=>{if(e.target===$('#note')){const r=$('#note').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#note').close()}};addEventListener('hashchange',event=>{if(event.newURL&&new URL(event.newURL).hash!==location.hash)return;render()});render();
